<?php
namespace App\Services;
use RuntimeException;
class LegacyMediaReader { public function path(string $legacyPath):string{$root=(string)config('legacy-media.uploads_path');if($root===''||!is_dir($root)||!is_readable($root))throw new RuntimeException('Legacy uploads path is unavailable.');$relative=ltrim((string)parse_url($legacyPath,PHP_URL_PATH),'/');$relative=preg_replace('#^wp-conten(?:t|u)/uploads/#','',$relative);$file=realpath($root.'/'.$relative);if($file===false||!str_starts_with($file,realpath($root).DIRECTORY_SEPARATOR))throw new RuntimeException('Legacy media path is invalid.');return $file;} public function inspect(string $legacyPath):array{$file=$this->path($legacyPath);$size=@getimagesize($file);return ['source'=>$file,'bytes'=>filesize($file),'checksum'=>hash_file('sha256',$file),'mime'=>$size['mime']??mime_content_type($file),'width'=>$size[0]??null,'height'=>$size[1]??null];} public function copyTo(string $legacyPath,string $destination):array{$data=$this->inspect($legacyPath);if(!copy($data['source'],$destination))throw new RuntimeException('V2 copy failed.');return $data;} }
